package com.prima.factory.device.simulator; import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import com.prima.factory.domain.*;
class TelemetryStateTest {@Test void countNeverDecreasesAndOnlyRuns(){var r=new SeededRandomSource(360);var running=new TelemetryState(10,14,50,10,40,EquipmentStatus.RUNNING,CommunicationStatus.CONNECTED);var next=running.next(r);assertTrue(next.count()>=10);var stopped=new TelemetryState(10,14,50,10,40,EquipmentStatus.WAITING,CommunicationStatus.CONNECTED);for(int i=0;i<20;i++)stopped=stopped.next(r);assertEquals(10,stopped.count());assertTrue(next.load()>=15&&next.load()<=95);}@Test void sameSeedIsRepeatable(){var a=new SeededRandomSource(360);var b=new SeededRandomSource(360);assertEquals(a.nextDouble(),b.nextDouble());}}
